record.field:
# ── DeepData Login ────────────────────────────────────────────────────── # GET /rest/login?user={user}&pass={password} # jsessionid is returned in the JSON response body (field "jsessionid"). # ────────────────────────────────────────────────────────────────────────
remote = self.remote_id cfg = {} try: cfg = json.loads(remote.connection_params or '{}') except Exception: cfg = {}
username = (cfg.get('username') or '').strip() password = (cfg.get('password') or '').strip() id_language = (cfg.get('idLanguage') or 'es').strip()
if not username or not password: raise Exception( "Missing DeepData credentials: set 'username' and 'password' " "in connection_params.")
# Build login URL — param is 'pass', not 'password' url = (base_url or '').rstrip('/') + '/rest/login' params = {'user': username, 'pass': password}
resp = request_retry('GET', url, params=params, timeout=timeout)
if resp.status_code >= 400: raise Exception( "DeepData login failed: HTTP %s - %s" % ( resp.status_code, (resp.text or '')[:500]))
# jsessionid comes from JSON body, not from Set-Cookie header try: body = resp.json() if resp.text else {} except Exception: raise Exception("DeepData login: invalid JSON response")
if isinstance(body, dict) and (body.get('codigo') or body.get('errorCode')): raise Exception( "DeepData login error: %s - %s" % ( body.get('codigo') or body.get('errorCode'), body.get('mensaje') or body.get('errorMessage', '')))
jsessionid = (body.get('jsessionid') or body.get('JSESSIONID') or '').strip()
if not jsessionid: raise Exception( "DeepData login succeeded but no 'jsessionid' in JSON response. " "Response: %s" % str(body)[:300])
# Store session in bag (ephemeral, not persisted) bag['jsessionid'] = jsessionid bag['idLanguage'] = id_language bag['login_name'] = body.get('name', '')

# ── DeepData: Build Sensor Plan ────────────────────────────────────────
# Reads mdm.measurement.device.sensor records linked to this
# remotecontrol and builds the plan for getMedidas calls.
#
# Each device represents a DeepData measure point and stores both
# installation_id and measure_point_id in its remotecontrol_params.
# Each sensor stores only variable_id in its remotecontrol_params.
#
# Groups sensors by installation for efficient API batching.
# ────────────────────────────────────────────────────────────────────────

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
today_str = fields.Date.today()

cfg = {}
try:
    cfg = json.loads(Remote.connection_params or '{}')
except Exception:
    cfg = {}

default_tz = cfg.get('timezone', 'Europe/Madrid')

condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id),
]

if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))

sensors = Sensor.search(condition)

# Build map of sensor_id -> most recent reading (single query)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]

# Build plan grouped by installation
# Structure: { installation_id: { info, sensors: [...] } }
installations_plan = {}
plan = []

for sensor in sensors:
    device = sensor.device_id

    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}

    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}

    installation_id = device_cfg.get('installation_id')
    measure_point_id = device_cfg.get('measure_point_id')
    variable_id = sensor_cfg.get('variable_id')

    if not installation_id or not measure_point_id or not variable_id:
        continue

    # Determine start date
    start_cfg = sensor_cfg.get('start_date') or device_cfg.get('start_date')
    last_reading_time = last_readings_map.get(sensor.id)

    if last_reading_time:
        try:
            initial_date = fields.Date.to_string(
                fields.Datetime.from_string(last_reading_time))
        except Exception:
            initial_date = str(last_reading_time)[:10]
    elif start_cfg:
        initial_date = start_cfg[:10]
    else:
        year_str = today_str[:4]
        initial_date = '%s-01-01' % year_str

    if isinstance(initial_date, unicode):
        initial_date = initial_date.encode('utf-8')

    inst_tz = device_cfg.get('timezone', default_tz)

    plan.append({
        'sensor_id': sensor.id,
        'device_id': device.id,
        'installation_id': installation_id,
        'installation_name': device_cfg.get('installation_name', ''),
        'measure_point_id': measure_point_id,
        'measure_point_name': device_cfg.get('measure_point_name', ''),
        'variable_id': variable_id,
        'variable_name': sensor_cfg.get('variable_name', ''),
        'variable_type': sensor_cfg.get('variable_type', ''),
        'variable_unit': sensor_cfg.get('variable_unit', ''),
        'timezone': inst_tz,
        'initial_date': initial_date,
    })

    # Group by installation for batched getMedidas calls
    inst_key = int(installation_id)
    if inst_key not in installations_plan:
        installations_plan[inst_key] = {
            'installation_id': installation_id,
            'installation_name': device_cfg.get('installation_name', ''),
            'timezone': inst_tz,
            'measure_points': {},
        }
    mp_key = int(measure_point_id)
    if mp_key not in installations_plan[inst_key]['measure_points']:
        installations_plan[inst_key]['measure_points'][mp_key] = {
            'measure_point_id': measure_point_id,
            'measure_point_name': device_cfg.get('measure_point_name', ''),
            'variables': [],
        }
    installations_plan[inst_key]['measure_points'][mp_key][
        'variables'].append({
            'variable_id': variable_id,
            'sensor_id': sensor.id,
            'device_id': device.id,
        })

bag['sensors_plan'] = plan
bag['installations_plan'] = installations_plan

# ── DeepData: Get Measures (getMedidas) ──────────────────────────────── # POST /rest/getMedidas — body Content-Type: text/plain (JSON string). # Payload: listInstallation > listMeasurePoint (with timeZone) > listVariables (int list). # # Response format: # [{"date": "DD-MM-YYYY HH:MM:SS", # "listValue": [{"idInstallation": "813", "idMeasurePoint": "23043", # "idVariable": "1", "value": 23.5}, ...]}, ...] # Note: date is a STRING in DD-MM-YYYY format (not a numeric timestamp). # Note: idInstallation/idMeasurePoint/idVariable are STRINGS (not ints). # # REST0003 → re-login and retry. # REST0012 → too many variables → split variable set in half, retry. # REST0013 → already queried, available in 24h → log and ABORT (no retry). # REST0011 → no data → log as info, continue. # REST0009 → error consulting → retry once with backoff. # ──────────────────────────────────────────────────────────────────────── import time as _time from datetime import datetime
Remote = self.remote_id plan = bag.get('sensors_plan') or [] installations_plan = bag.get('installations_plan') or {} jsessionid = bag.get('jsessionid')
if not jsessionid: raise Exception("Missing JSESSIONID in bag. Run Login action first.")
cfg = {} try: cfg = json.loads(Remote.connection_params or '{}') except Exception: cfg = {}
api_base = (base_url or '').rstrip('/') id_language = bag.get('idLanguage') or cfg.get('idLanguage', 'es') today_str = fields.Date.today() end_date_str = today_str + ' 23:59:59'
# Maximum number of variables per API call. The DeepData API returns # REST0012 when too many variables are requested at once, and that # first failed call already triggers a 24 h cooldown (REST0013). # Pre-splitting avoids hitting the limit entirely. Default: 5. max_vars_per_call = int(cfg.get('max_vars_per_call', 5))
# Build sensor lookup: (installation_id, measure_point_id, variable_id) -> sensor_id, device_id sensor_lookup = {} for s in plan: key = (int(s['installation_id']), int(s['measure_point_id']), int(s['variable_id'])) sensor_lookup[key] = { 'sensor_id': s['sensor_id'], 'device_id': s['device_id'], }
total_upserts = 0 total_errors = 0 total_api_calls = 0 items = [] relogin_count = 0 MAX_RELOGINS = 3
def _do_login(): """Re-login: param is 'pass', jsessionid from JSON body.""" login_url = api_base + '/rest/login' login_params = { 'user': (cfg.get('username') or '').strip(), 'pass': (cfg.get('password') or '').strip(), } login_resp = request_retry( 'GET', login_url, params=login_params, timeout=timeout) if login_resp.status_code >= 400: raise Exception( "DeepData re-login failed: HTTP %s" % login_resp.status_code) try: login_body = login_resp.json() except Exception: raise Exception("DeepData re-login: invalid JSON response") new_jsessionid = ( login_body.get('jsessionid') or login_body.get('JSESSIONID') or '').strip() if not new_jsessionid: raise Exception("DeepData re-login: no jsessionid in response") return new_jsessionid
def _parse_date(date_val): """Convert API date to Odoo datetime string (YYYY-MM-DD HH:MM:SS).
The DeepData API returns date as a string in DD-MM-YYYY HH:MM:SS format (e.g. '10-03-2026 00:15:00'). We also handle numeric timestamps (sec or ms) as a fallback, and YYYY-MM-DD strings. """ s = str(date_val).strip() if date_val is not None else '' if not s: return ''
# ── Try DD-MM-YYYY HH:MM:SS (actual API format) ──────────────── if len(s) >= 10 and s[2] == '-' and s[5] == '-': try: dt = datetime.strptime(s, '%d-%m-%Y %H:%M:%S') return dt.strftime('%Y-%m-%d %H:%M:%S') except ValueError: pass
# ── Already YYYY-MM-DD HH:MM:SS ──────────────────────────────── if len(s) >= 10 and s[4] == '-' and s[7] == '-': return s
# ── Numeric timestamp (sec or ms) — fallback ────────────────── try: ts_num = int(s) ts_secs = ts_num / 1000.0 if ts_num > 9999999999 else float(ts_num) return datetime.fromtimestamp(ts_secs).strftime('%Y-%m-%d %H:%M:%S') except (ValueError, TypeError, OSError): pass
return s # last resort: return as-is
def _call_medidas(payload_dict, session_id): """POST /rest/getMedidas with text/plain body.""" url = api_base + '/rest/getMedidas' hdrs = { 'Cookie': 'JSESSIONID=%s' % session_id, 'Content-Type': 'text/plain', 'Accept': 'application/json', } return request_retry( 'POST', url, data=json.dumps(payload_dict), headers=hdrs, timeout=timeout)
def _build_payload(inst_data, var_ids, start_date, end_date): """Build getMedidas payload: listInstallation > listMeasurePoint > listVariables.""" list_mp = [] for mp_id, mp_data in inst_data['measure_points'].items(): mp_vars = [ int(v['variable_id']) for v in mp_data['variables'] if v['variable_id'] in var_ids ] if mp_vars: list_mp.append({ 'idMeasurePoint': mp_data['measure_point_id'], 'timeZone': inst_data.get('timezone', ''), 'listVariables': mp_vars, }) return { 'startDate': start_date, 'endDate': end_date, 'idLanguage': id_language, 'listInstallation': [{ 'idInstallation': inst_data['installation_id'], 'listMeasurePoint': list_mp, }], }
def _all_var_ids(inst_data): ids = set() for mp_data in inst_data['measure_points'].values(): for v in mp_data['variables']: ids.add(v['variable_id']) return ids
def _split_vars(var_ids): """Split variable id set in half.""" lst = sorted(var_ids) mid = max(1, len(lst) // 2) return set(lst[:mid]), set(lst[mid:])
def _process(inst_id, inst_data, var_ids, start_date, end_date, session_id, depth=0): """Call getMedidas for one installation. Returns (u, e, c, session, log).""" global relogin_count if depth > 8: return (0, 1, 0, session_id, [{'inst': inst_id, 'error': 'Max depth reached'}])
payload = _build_payload(inst_data, var_ids, start_date, end_date) upserts = 0 errors = 0 api_calls = 0 log = []
try: resp = _call_medidas(payload, session_id) api_calls += 1 try: body = resp.json() if resp.text else {} except Exception: body = {}
# ── API error codes ──────────────────────────────────── # The API returns errors as {"codigo": "RESTxxxx", "mensaje": "..."} # with HTTP 400. We check both Spanish ("codigo") and the # English names documented in the spec ("errorCode") for safety. if isinstance(body, dict) and (body.get('codigo') or body.get('errorCode')): ec = body.get('codigo') or body.get('errorCode', '') em = body.get('mensaje') or body.get('errorMessage', '') or ''
if ec == 'REST0003': if relogin_count >= MAX_RELOGINS: raise Exception("Max re-logins (%s) exceeded" % MAX_RELOGINS) relogin_count += 1 session_id = _do_login() bag['jsessionid'] = session_id return _process(inst_id, inst_data, var_ids, start_date, end_date, session_id, depth)
elif ec == 'REST0012': # Too many variables → split var set in half if len(var_ids) <= 1: log.append({'inst': inst_id, 'error': 'REST0012: cannot split (1 variable)', 'start': start_date}) errors += 1 return (upserts, errors, api_calls, session_id, log) half1, half2 = _split_vars(var_ids) for half in [h for h in [half1, half2] if h]: su, se, sc, session_id, sl = _process( inst_id, inst_data, half, start_date, end_date, session_id, depth + 1) upserts += su errors += se api_calls += sc log.extend(sl) return (upserts, errors, api_calls, session_id, log)
elif ec == 'REST0013': # Already queried — do NOT retry, log and abort log.append({'inst': inst_id, 'warning': 'REST0013: %s (skip, do not retry)' % em, 'start': start_date, 'end': end_date}) return (upserts, errors, api_calls, session_id, log)
elif ec == 'REST0011': # No data available — not an error log.append({'inst': inst_id, 'info': 'REST0011: no data for requested range', 'start': start_date, 'end': end_date}) return (upserts, errors, api_calls, session_id, log)
elif ec == 'REST0009': # Error consulting → retry once with backoff if depth == 0: _time.sleep(5.0) return _process(inst_id, inst_data, var_ids, start_date, end_date, session_id, depth + 1) log.append({'inst': inst_id, 'error': 'REST0009: %s' % em, 'start': start_date}) errors += 1 return (upserts, errors, api_calls, session_id, log)
else: # REST0002 (missing params), REST0007 (bad JSON), others log.append({'inst': inst_id, 'error': '%s: %s' % (ec, em), 'start': start_date}) errors += 1 return (upserts, errors, api_calls, session_id, log)
if resp.status_code >= 400: log.append({'inst': inst_id, 'status': resp.status_code, 'error': (resp.text or '')[:400], 'start': start_date}) errors += 1 return (upserts, errors, api_calls, session_id, log)
# ── Process successful response ──────────────────────── medidas = body if isinstance(body, list) else body.get('medidas', []) readings_sample = []
for medida in medidas: if not isinstance(medida, dict): continue date_ts = medida.get('date') list_value = medida.get('listValue') or [] if date_ts is None or not isinstance(list_value, list): errors += 1 continue date_str = _parse_date(date_ts)
for entry in list_value: if not isinstance(entry, dict): errors += 1 continue e_inst = entry.get('idInstallation') e_mp = entry.get('idMeasurePoint') e_var = entry.get('idVariable') e_val = entry.get('value') if e_inst is None or e_mp is None or e_var is None \ or e_val is None: errors += 1 continue
lookup_key = (int(e_inst), int(e_mp), int(e_var)) sensor_info = sensor_lookup.get(lookup_key) if not sensor_info: continue # variable not configured in Odoo
try: valf = float(e_val) except (ValueError, TypeError): errors += 1 continue
Remote.upsert( 'mdm.measurement.device.sensor.reading', {'sensor_id': sensor_info['sensor_id'], 'measurement_time': date_str}, {'value': valf, 'device_id': sensor_info['device_id']}, ) upserts += 1 if len(readings_sample) < 5: readings_sample.append({ 'ts': date_str, 'inst': e_inst, 'mp': e_mp, 'var': e_var, 'val': valf, })
log.append({ 'inst': inst_id, 'start': start_date, 'end': end_date, 'status': resp.status_code, 'medidas_count': len(medidas), 'upserts': upserts, 'errors': errors, 'sample': readings_sample, })
except Exception as e: err_str = str(e) if 'SESSION_EXPIRED' in err_str or 'REST0003' in err_str: if relogin_count < MAX_RELOGINS: relogin_count += 1 session_id = _do_login() bag['jsessionid'] = session_id return _process(inst_id, inst_data, var_ids, start_date, end_date, session_id, depth) log.append({'inst': inst_id, 'error': err_str, 'start': start_date}) errors += 1
return (upserts, errors, api_calls, session_id, log)
# ── Main loop ────────────────────────────────────────────────────────── for inst_id, inst_data in installations_plan.items(): inst_start = today_str for s in plan: if int(s['installation_id']) == int(inst_id): if s['initial_date'] < inst_start: inst_start = s['initial_date']
all_vars = sorted(_all_var_ids(inst_data))
# Pre-split variables into chunks of max_vars_per_call to avoid # REST0012 (too many variables) which triggers the 24h cooldown. chunks = [] for i in range(0, len(all_vars), max_vars_per_call): chunks.append(set(all_vars[i:i + max_vars_per_call])) if not chunks: chunks = [set(all_vars)]
for chunk in chunks: u, e, c, jsessionid, inst_log = _process( inst_id, inst_data, chunk, inst_start + ' 00:00:00', end_date_str, jsessionid)
total_upserts += u total_errors += e total_api_calls += c items.extend(inst_log) _time.sleep(0.5)
bag['jsessionid'] = jsessionid
# ── Create audit attachment ──────────────────────────────────────────── audit = { 'executed_at': fields.Datetime.now(), 'end_date': today_str, 'id_language': id_language, 'total_upserts': total_upserts, 'total_errors': total_errors, 'total_api_calls': total_api_calls, 'relogins': relogin_count, 'installations_processed': len(installations_plan), 'items': items, }
b64 = base64.b64encode( json.dumps(audit, ensure_ascii=False, indent=2).encode('utf-8')) fname = 'deepdata_measures_%s.json' % ( fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_'))
att = env['ir.attachment'].create({ 'name': fname, 'datas_fname': fname, 'datas': b64, 'mimetype': 'application/json', 'res_model': 'remotecontrol', 'res_id': Remote.id, })
Remote.message_post( body=u'[DeepData] Measures: upserts=%s errors=%s api_calls=%s ' u'relogins=%s installations=%s lang=%s' % ( total_upserts, total_errors, total_api_calls, relogin_count, len(installations_plan), id_language), attachment_ids=[att.id], )
bag['upserts'] = total_upserts bag['errors'] = total_errors bag['audit_attachment_id'] = att.id
